"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7355],{96709:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"PlaceUtility","desc":"Which kind of place this server or client runs in, and which experience and\\nplace ids go with it. Everything is worked out once, the first time the module\\nis required; later changes to the inputs have no effect.\\n\\nThe kind comes from the `ReplicatedStorage.Environment` StringValue that each\\nRojo project sets: `Single` (a one-place game), `Main` (the starter place of a\\ntwo-place game) or `Level` (its gameplay place). The module waits for that\\nvalue to exist. Any other value warns once and leaves all three flags false.\\n\\n`isProduction` is true when `game.GameId` is `GameData.liveExperienceId`. The\\nthree ids then come from the live set in `GameData`, otherwise from the dev\\nset. `placeId` is always the starter place, in a `Level` place too.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","source":{"line":20,"path":"src/Shared/Modules/PlaceUtility.luau"}}')}}]);